import{_ as i,o as a,c as l,a2 as t}from"./chunks/framework.iXqqCa-C.js";const r="/images/misskey-drive.webp",m=JSON.parse('{"title":"网盘","description":"","frontmatter":{},"headers":[],"relativePath":"guide/misskey/drive.md","filePath":"guide/misskey/drive.md","lastUpdated":1793501934000}'),s={name:"guide/misskey/drive.md"};function o(n,e,d,c,_,h){return a(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="网盘" tabindex="-1">网盘 <a class="header-anchor" href="#网盘" aria-label="Permalink to &quot;网盘&quot;">​</a></h1><p>网盘（Drive）保存你上传的所有文件，发帖上传的图片、视频都在这里，可以重复使用。</p><p><img src="'+r+'" alt="网盘"></p><h2 id="管理文件" tabindex="-1">管理文件 <a class="header-anchor" href="#管理文件" aria-label="Permalink to &quot;管理文件&quot;">​</a></h2><ul><li>通过侧栏「网盘」进入，可新建文件夹、移动、重命名、删除文件。</li><li><strong>框选与拖拽</strong>：电脑上从空白处按下拖动可框选多个文件；手机上长按文件后拖动可移入文件夹，长按空白处可框选。</li><li>进入子文件夹后，浏览器返回键可逐级返回上一层。</li><li>点击文件可查看文件信息和引用了该文件的帖子。</li><li>文件可标记为<strong>敏感内容</strong>，在时间线中默认折叠显示。</li><li>单个文件可以在不同帖子中重复引用。删除文件后，引用处显示「已被清理」占位卡片，并标注文件原主人。</li></ul><h2 id="图片装饰" tabindex="-1">图片装饰 <a class="header-anchor" href="#图片装饰" aria-label="Permalink to &quot;图片装饰&quot;">​</a></h2><ul><li><strong>添加边框</strong>：为图片加边框和元数据标签。</li><li><strong>添加水印</strong>：为图片叠加水印。</li></ul><h2 id="容量与清理" tabindex="-1">容量与清理 <a class="header-anchor" href="#容量与清理" aria-label="Permalink to &quot;容量与清理&quot;">​</a></h2><ul><li>总容量、单个文件大小上限和可上传的文件类型由服务器策略决定。</li><li>「设置 → 网盘」：查看容量与使用量统计，设置默认上传文件夹、上传时默认压缩等级、是否保留原文件名、总是标记为敏感内容、自动检测敏感内容，以及默认边框和水印预设。</li><li>「网盘清理」：按文件大小或创建时间排序列出文件，便于批量删除。</li><li>第三方客户端上传、下载文件出问题时，改用浏览器访问网站操作。</li></ul>',9)])])}const p=i(s,[["render",o]]);export{m as __pageData,p as default};
